// TH15 bullet appearance constants used by this card (see transcribe/th15/touhou-bullets.ecl).
// Source etSprite(0, 8, 10) -> type 8 rice, color 10.
const TH15_RICE: int = 480;

// TH15 Stage 5 mid-stage wave: MainSub07 second half (st05.ecl.txt:1612-1623).
// 32 rounds of a GirlA06 pair (left normal / right mirrored), 17 frames apart.
// Dependencies: GirlA06 (550-559), GirlA06_at (561-576), GirlA06_at2 (578-622).
//
// Per-enemy behaviour (GirlA06_at):
//   setHurtbox(24,24) -> r=12, setHitbox(16,16) -> r=8
//   moveVel(F0, 3), moveVelTime(120, mode1, -0.19634955, 2),
//   wait(120), moveVelTime(60, mode4, 0.7853982, 4), then keep alive.
// Firing (GirlA06_at2): ring of rice (count 6/8/10/12 by rank), speed 1,
//   first shot after wait(10 + RAND%40), then one ring per 80 frames.
//   EX per bullet: ANIM(a=1) / BRIGHT / VELTIME(60, target speed 1) / STEP(1 seg, +-F1)
//   / EX_LASER line (sprite 8, color 10, width 16, length 32).  VELTIME holds the
//   bullet straight for 60 frames, then STEP turns it by F1 = +-45deg and the
//   bullet is replaced by a line laser.  The firing task waits the same 60 frames
//   and spawns the rod from the recorded muzzle position/angle (no per-bullet task).
//   Bullets fired while the enemy is still alive convert; off-screen enemies stop.

const TIME_LIMIT: int = 1324;
const OPENING_BUFFER: int = 120;

// Rice bullet is removed after the 60-frame hold, when its EX would create the
// laser (EX_LASER d=1 deletes the parent bullet).
xformdef LIFE_AFTER_STEP {
    set_life(60);
}

async sub girl_fire(is_mirror: int) {
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 10);
    sh_ring(0, 1);                 // etAim mode 3: fixed-direction full ring
    sh_speed(0, 1fx, 0fx);         // etSpeed(1.0, 0.2), one layer
    sh_dist(0, -4fx);              // ANIM a=1 birth retreat: position -= 4*velocity
    sh_xform(0, LIFE_AFTER_STEP);

    var rank: int = global(GVAR_RANK);
    var n: int = 6;                // etCount from difficulty push 6/8/10/12
    var spd: fx = 4fx;             // EX_LASER s = 4.0/6.0/6.0/6.4
    var act: int = 32;             // EX_LASER line travel to length limit ~128
    if rank == 1 { n = 8; spd = 6fx; act = 21; }
    else if rank == 2 { n = 10; spd = 6fx; act = 21; }
    else if rank >= 3 { n = 12; spd = 6.4fx; act = 20; }
    sh_count(0, n, 1);

    var turn: int = 8192;          // STEP r=%F1 = +45deg (left)
    if is_mirror != 0 { turn = -8192; }   // -45deg (right)

    wait(10 + rand(40));           // wait(10 + RAND % 40)
    var it: int = 0;
    while it < 80 {
        // etAngle base = pi/2 + RANDF2*pi/6, one draw per wave.
        var u: fx = (rand(65536) - 32768) as fx / 32768;
        var off: int = (5461fx * u) as int;
        var alpha: angle = 90deg + (off as angle);
        var x0: fx = $self_x;
        var y0: fx = $self_y;
        sh_angle(0, alpha, 0deg);
        sh_fire(0);
        // VELTIME(60) holds the rice straight, then STEP turns it by F1 and the
        // bullet becomes a line laser: width 16 -> target 8, length 32, speed s.
        wait(60);
        for j in 0..n {
            var d: int = (alpha as int) + ((j * 65536) / n);
            var lx: fx = x0 + 56fx * cos(d as angle);
            var ly: fx = y0 + 56fx * sin(d as angle);
            var la: int = d + turn;
            var h: int = laser(10, lx, ly, la as angle, 32fx, 8fx, 3, act - 3, 0);
            lz_speed(h, spd, 32fx);
        }
        wait(20);
        it = it + 1;
    }
}

// GirlA06_at: source moves with F0, then mode1 to -11.25deg / speed 2, then
// mode4 to +45deg / speed 4.  Mirrored side uses 180deg-angle for motion.
async sub girl_a06(is_mirror: int, f0: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_fire(is_mirror);

    var a0: int = f0 as int;
    var a1: int = -2048;           // -0.19634955 rad = -11.25deg
    var a2: int = 8192;            //  0.7853982 rad = +45deg
    if is_mirror != 0 {
        a0 = 32768 - a0;
        a1 = 32768 - a1;
        a2 = 32768 - a2;
    }
    move_vel(0, a0 as angle, 3fx, EASE_LINEAR);
    move_vel(120, a1 as angle, 2fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a2 as angle, 4fx, EASE_QUAD_OUT);
    loop { wait(1000); }
}

// MainSub07 second half: $B=32 rounds.  Each round draws F0 once (shared by the
// pair), then an independent y offset per enemy (source order: F0, left y, right y).
async sub pattern() {
    wait(OPENING_BUFFER);
    var b: int = 32;
    while b > 0 {
        var u0: fx = (rand(65536) - 32768) as fx / 32768;
        var f0: int = 4096 + ((3641fx * u0) as int);   // 22.5deg + RANDF2*20deg
        var u1: fx = (rand(65536) - 32768) as fx / 32768;
        var yl: fx = 64fx + 32fx * u1;
        var u2: fx = (rand(65536) - 32768) as fx / 32768;
        var yr: fx = 64fx + 32fx * u2;
        _ = spawn_enemy(-224fx, yl, 50, 0, 0, 0, girl_a06(0, f0 as angle));
        _ = spawn_enemy(224fx, yr, 50, 0, 0, 0, girl_a06(1, f0 as angle));
        wait(17);                  // wait(17)
        b = b - 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
